  'boon.rune.q': ['Οι λέξεις των Λιθογενών, χαραγμένες στο δέρμα σου.', 'The words of the Stoneborn, cut into your skin.'],
  'boon.amber': ['Δάκρυ του Κεχριμπαριού', 'Amber Tear'], 'boon.amber.d': ['+15 ζωή ανά χτύπημα, +10 ζωή ανά δευτερόλεπτο', '+15 life per hit, +10 life per second'],
  'boon.amber.q': ['Ό,τι πληγώνει το δέντρο, το κλείνει με δάκρυ.', 'What wounds the tree, it closes with a tear.'],
