  'boon.hart.q': ['Τρέξε σαν το Λευκό Ελάφι· η στάχτη δεν σε προλαβαίνει.', 'Run like the White Hart; the ash cannot catch you.'],
  'boon.root': ['Βαθιά Ρίζα', 'Deep Root'], 'boon.root.d': ['+10% πιθανότητα απόκρουσης, +8% ζωή', '+10% block chance, +8% life'],
  'boon.root.q': ['Ό,τι έχει ρίζα, δεν το παίρνει ο άνεμος.', 'What has roots, the wind does not take.'],
